// Aggregate the last 7 days of History rows and build an HTML report.
const now = new Date();
const cutoff = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

// Drop empty-json items (alwaysOutputData emits one {} item when the sheet is empty).
const allRows = $input.all()
  .map((i) => i.json)
  .filter((r) => r && Object.keys(r).length > 0);

// Filter to the last 7 days by timestamp.
const recent = allRows.filter((r) => {
  if (!r.timestamp) return false;
  const t = new Date(r.timestamp);
  if (isNaN(t.getTime())) return false;
  return t >= cutoff;
});

const dateLabel = now.toISOString().slice(0, 10);

// No data in the past week -> brief no-changes email.
if (recent.length === 0) {
  const emptyHtml =
    '<div style="font-family:Arial,sans-serif;color:#333;">' +
    '<h2>Weekly Scrape Summary — ' + dateLabel + '</h2>' +
    '<p>No changes recorded this week.</p>' +
    '</div>';
  return [{ json: { hasData: false, dateLabel, html: emptyHtml } }];
}

// Group per source_url + field_name.
const groups = {};
for (const r of recent) {
  const key = (r.source_url || '') + '||' + (r.field_name || '');
  if (!groups[key]) {
    groups[key] = {
      source_url: r.source_url || '',
      field_name: r.field_name || '',
      changes: 0,
      latestValue: null,
      latestTs: '',
      latestSummary: '',
      numericValues: [],
    };
  }
  const g = groups[key];
  g.changes += 1;

  const ts = r.timestamp || '';
  if (ts >= g.latestTs) {
    g.latestTs = ts;
    g.latestValue = r.value;
    g.latestSummary = r.ai_summary || '';
  }

  const num = typeof r.value === 'number' ? r.value : parseFloat(String(r.value).replace(/[^0-9.\-]/g, ''));
  if (!isNaN(num) && String(r.value).trim() !== '') {
    g.numericValues.push(num);
  }
}

const aggregates = Object.keys(groups).map((k) => {
  const g = groups[k];
  const isNumeric = g.numericValues.length > 0;
  return {
    source_url: g.source_url,
    field_name: g.field_name,
    changes: g.changes,
    latestValue: g.latestValue,
    min: isNumeric ? Math.min(...g.numericValues) : '',
    max: isNumeric ? Math.max(...g.numericValues) : '',
    latestSummary: g.latestSummary,
  };
});

// Build HTML table.
let rowsHtml = '';
for (const a of aggregates) {
  rowsHtml +=
    '<tr>' +
    '<td style="padding:6px;border:1px solid #ddd;">' + a.source_url + '</td>' +
    '<td style="padding:6px;border:1px solid #ddd;">' + a.field_name + '</td>' +
    '<td style="padding:6px;border:1px solid #ddd;text-align:center;">' + a.changes + '</td>' +
    '<td style="padding:6px;border:1px solid #ddd;">' + (a.latestValue ?? '') + '</td>' +
    '<td style="padding:6px;border:1px solid #ddd;text-align:right;">' + a.min + '</td>' +
    '<td style="padding:6px;border:1px solid #ddd;text-align:right;">' + a.max + '</td>' +
    '<td style="padding:6px;border:1px solid #ddd;">' + a.latestSummary + '</td>' +
    '</tr>';
}

const html =
  '<div style="font-family:Arial,sans-serif;color:#333;">' +
  '<h2>Weekly Scrape Summary — ' + dateLabel + '</h2>' +
  '<p>' + recent.length + ' change(s) recorded across ' + aggregates.length + ' tracked field(s) in the last 7 days.</p>' +
  '<table style="border-collapse:collapse;width:100%;font-size:13px;">' +
  '<thead><tr style="background:#f2f2f2;">' +
  '<th style="padding:6px;border:1px solid #ddd;text-align:left;">Source URL</th>' +
  '<th style="padding:6px;border:1px solid #ddd;text-align:left;">Field</th>' +
  '<th style="padding:6px;border:1px solid #ddd;">Changes</th>' +
  '<th style="padding:6px;border:1px solid #ddd;text-align:left;">Latest Value</th>' +
  '<th style="padding:6px;border:1px solid #ddd;">Min</th>' +
  '<th style="padding:6px;border:1px solid #ddd;">Max</th>' +
  '<th style="padding:6px;border:1px solid #ddd;text-align:left;">Latest AI Summary</th>' +
  '</tr></thead>' +
  '<tbody>' + rowsHtml + '</tbody>' +
  '</table>' +
  '</div>';

return [{ json: { hasData: true, dateLabel, html } }];
